using Npgsql;using SanSo.Api.V2;using SanSo.Api.V5;using Xunit;
namespace SanSo.Api.V5.Tests;
public sealed class PostgresInventoryConcurrencyV2Tests
{
 [Fact]public async Task LastUnitHasExactlyOneWinnerAndSourceRetryIsIdempotent(){var cs=Environment.GetEnvironmentVariable("SANSO_RUNTIME_POSTGRES");if(string.IsNullOrWhiteSpace(cs))return;var tenant=Guid.NewGuid();var product=Guid.NewGuid();var location=Guid.NewGuid();var sku=$"LAST-{Guid.NewGuid():N}";await Seed(cs,tenant,product,location,sku);await using var source=NpgsqlDataSource.Create(cs);var store=new PostgresInventoryStoreV2(source);var first=Attempt(store,tenant.ToString(),sku,"reserve-a");var second=Attempt(store,tenant.ToString(),sku,"reserve-b");var results=await Task.WhenAll(first,second);Assert.Single(results,x=>x.Success);Assert.Single(results,x=>!x.Success&&x.Conflict);var winner=results.Single(x=>x.Success);var retry=await store.Reserve(tenant.ToString(),sku,1,winner.SourceKey,default);Assert.Equal(0,retry.Available);Assert.Equal(1,retry.Version);await using var c=new NpgsqlConnection(cs);await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="SELECT reserved,version,(SELECT count(*) FROM inventory_movements WHERE organization_id=$1 AND type='RESERVE') FROM inventory_balances WHERE organization_id=$1 AND product_id=$2 AND location_id=$3";q.Parameters.AddWithValue(tenant);q.Parameters.AddWithValue(product);q.Parameters.AddWithValue(location);await using var r=await q.ExecuteReaderAsync();Assert.True(await r.ReadAsync());Assert.Equal(1,r.GetInt32(0));Assert.Equal(1,r.GetInt64(1));Assert.Equal(1,r.GetInt64(2));}
 static async Task<(bool Success,bool Conflict,string SourceKey)> Attempt(PostgresInventoryStoreV2 store,string tenant,string sku,string key){try{await store.Reserve(tenant,sku,1,key,default);return(true,false,key);}catch(InventoryConflictException){return(false,true,key);}}static async Task Seed(string cs,Guid tenant,Guid product,Guid location,string sku){await using var c=new NpgsqlConnection(cs);await c.OpenAsync();await using var tx=await c.BeginTransactionAsync();foreach(var(sql,args)in new[]{("INSERT INTO organizations(id,slug,name) VALUES($1,$2,'Inventory test')",new object[]{tenant,$"inventory-{tenant:N}"}),("INSERT INTO products(id,organization_id,name,canonical_sku) VALUES($1,$2,'Last unit',$3)",new object[]{product,tenant,sku}),("INSERT INTO inventory_locations(id,organization_id,code,name) VALUES($1,$2,'MAIN','Main')",new object[]{location,tenant}),("INSERT INTO inventory_balances(organization_id,product_id,location_id,on_hand,reserved,quarantine) VALUES($1,$2,$3,1,0,0)",new object[]{tenant,product,location})}){await using var q=c.CreateCommand();q.Transaction=tx;q.CommandText=sql;for(var i=0;i<args.Length;i++)q.Parameters.AddWithValue(args[i]);await q.ExecuteNonQueryAsync();}await tx.CommitAsync();}
}
